<script lang="ts">
import {onMount,tick} from 'svelte';import {api,type Book,type Shelf,type Copy} from '../../lib/api';import BookForm from './BookForm.svelte';import CopyArchive from './CopyArchive.svelte';
export let bookId:number;
let book:Book|null=null;let shelves:Shelf[]=[];let error='';let loading=true;let editing=false;let busy=false;let message='';let addShelf='';let copyKey='';let copyPayload='';
async function load(){try{book=await api<Book>(`/api/books/${bookId}`);shelves=await api<Shelf[]>('/api/shelves');}catch(e){error=(e as Error).message;}finally{loading=false;}}
onMount(()=>{load();const refresh=()=>load();window.addEventListener('focus',refresh);window.addEventListener('library-inventory-changed',refresh);return()=>{window.removeEventListener('focus',refresh);window.removeEventListener('library-inventory-changed',refresh);};});
async function addCopy(){if(!book)return;busy=true;error='';const body={shelf_id:addShelf?Number(addShelf):null};const payload=JSON.stringify(body);if(payload!==copyPayload){copyKey=crypto.randomUUID();copyPayload=payload;}try{book=await api<Book>(`/api/books/${book.id}/copies`,{...body,request_key:copyKey});copyPayload='';message='Another copy added.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
async function move(c:Copy,e:Event){busy=true;error='';let saved=false;const source=e.target as HTMLElement;try{const value=(e.target as HTMLSelectElement).value;await api(`/api/copies/${c.id}`,{shelf_id:value?Number(value):null,revision:c.revision},'PATCH');await load();message='Shelf updated.';saved=true;}catch(e){error=(e as Error).message;await load();}finally{busy=false;await tick();if(saved&&!error)window.dispatchEvent(new CustomEvent('library-shelf-saved',{detail:{source}}));}}
</script>
<div class="book-detail_wrap">{#if error}<p role="alert" class="library-error">{error}</p>{/if}{#if loading}<p>Loading shelf and lending status…</p>{:else if book}<div class="library-actions"><span class="library-badge">{book.count} {book.count===1?'copy':'copies'} · {book.available} available</span><button class="library-button secondary" onclick={()=>editing=!editing}>{editing?'Close editor':'Edit book details'}</button></div>{#if editing}<BookForm draft={{...book}} {shelves} editing={book} saved={()=>window.location.reload()}/>{/if}<section class="book-detail_copies"><h3>Your copies</h3>{#each book.copies as c (c.id)}<div class="book-detail_copy"><strong>{c.label}</strong><span class="library-badge">{c.out?'On loan':'Available'}</span><label class="library-field">Home shelf<select value={c.shelf_id||''} disabled={busy} onchange={(e)=>move(c,e)}><option value="">Unassigned</option>{#each shelves as s}<option value={s.id}>{s.bookcase} / {s.name}</option>{/each}</select></label><CopyArchive copy={c}/></div>{/each}<div class="book-detail_add"><label class="library-field">Shelf for another copy<select bind:value={addShelf}><option value="">Unassigned</option>{#each shelves as s}<option value={s.id}>{s.bookcase} / {s.name}</option>{/each}</select></label><button class="library-button secondary" disabled={busy} onclick={addCopy}>+ Add another copy</button></div><p class="library-help">Only use this when you own another physical copy of this edition.</p></section><p role="status">{message}</p>{/if}</div>
<style>@layer components {.book-detail_wrap{display:grid;gap:var(--space-5)}.book-detail_layout{display:flex;gap:var(--space-6);align-items:start;@media(width<48rem){flex-direction:column}}.book-detail_cover{width:10rem;aspect-ratio:2/3;background:#e8e3d8;color:#33483a;padding:var(--space-3);display:flex;flex-direction:column;justify-content:space-between;font-family:Georgia,serif;box-shadow:inset .25rem 0 #0001}.book-detail_content{display:grid;gap:var(--space-3);h2{font-family:Georgia,serif;font-size:var(--h3)}dl{display:grid;gap:var(--space-2);div{display:flex;gap:var(--space-4)}dt{width:7rem;color:var(--text-2)}dd{margin:0}}}.book-detail_copies{display:grid;gap:var(--space-4);h3{font-size:var(--h5)}}.book-detail_copy{display:grid;grid-template-columns:1fr auto 2fr;gap:var(--space-4);align-items:center;padding:var(--space-4);border:var(--border-width) solid var(--border);background:var(--background-3);border-radius:var(--radius-main);@media(width<48rem){grid-template-columns:1fr;}}.book-detail_copy :global(.archive_wrap){grid-column:1/-1}.book-detail_add{display:flex;align-items:end;gap:var(--space-3);flex-wrap:wrap}}</style>
